fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Preallocate the resulting vector with the combined capacity
    let mut result = Vec::with_capacity(v1.len() + v2.len());

    // Append all elements of v1
    for &item in v1.iter() {
        result.push(item);
    }
    // Append all elements of v2
    for &item in v2.iter() {
        result.push(item);
    }

    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // first is assumed to be non-empty
    let n = first.len();
    assert!(n >= 1, "The first vector must be non-empty");

    // Take all but the last element of `first`
    let mut prefix = Vec::with_capacity(n - 1);
    for &item in first.iter().take(n - 1) {
        prefix.push(item);
    }

    // Append all of `second` after that prefix
    append_vectors(&prefix, second)
}

